package de.ambertation.wover.potions.api;

import net.minecraft.core.Holder;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.alchemy.Potion;

/**
 * Collects the brewing-stand recipes a mod wants to add on top of vanilla's.
 * <p>
 * This is the replacement for the {@code PotionBrewing.Builder} that {@link OnBootstrapPotions} used to
 * receive: 26.3 deleted {@code PotionBrewing} entirely and turned brewing into part of the recipe system
 * ({@code minecraft:brewing} recipes in the {@code minecraft:recipe} datapack registry, generated by
 * {@link net.minecraft.data.recipes.BrewingProvider}). The four methods below are deliberately named and
 * shaped exactly like the ones {@code PotionBrewing.Builder} offered, so porting a subscriber is a change
 * of parameter type and nothing else.
 * <p>
 * Calls are recorded rather than executed immediately, and replayed into the correct phase of vanilla's
 * {@code BrewingProvider} lifecycle ({@code addContainers()} &rarr; {@code addContainerTransformations()}
 * &rarr; {@code buildMixes()} &rarr; {@code buildTransformations()}). Order between calls therefore does not
 * matter, just as it did not for {@code PotionBrewing.Builder}, and your containers/mixes are combined with
 * vanilla's: a mix you add is brewable in every vanilla container, and a container you add works with every
 * vanilla potion.
 */
public interface BrewingBuilder {
    /**
     * Registers an item as a potion container, i.e. an item that can hold potion contents and be placed in
     * the brewing stand's bottle slots.
     * <p>
     * Equivalent to {@code PotionBrewing.Builder#addContainer}.
     *
     * @param container The container item.
     */
    void addContainer(Item container);

    /**
     * Registers a conversion between two potion containers, e.g. vanilla's
     * {@code potion + gunpowder -> splash_potion}. The conversion is applied to every potion known to the
     * brewing system, so one call yields one recipe per potion.
     * <p>
     * Equivalent to {@code PotionBrewing.Builder#addContainerRecipe}. The container must have been declared
     * with {@link #addContainer(Item)} (by you or by vanilla) or the recipe generator rejects it.
     *
     * @param container The container the conversion starts from.
     * @param reagent   The item placed in the brewing stand's ingredient slot.
     * @param result    The container the conversion produces.
     */
    void addContainerRecipe(Item container, Item reagent, Item result);

    /**
     * Registers a potion mix: brewing {@code reagent} on top of {@code from} yields {@code to}. The mix is
     * generated for every registered container.
     * <p>
     * Equivalent to {@code PotionBrewing.Builder#addMix}.
     *
     * @param from    The potion being brewed on.
     * @param reagent The item placed in the brewing stand's ingredient slot.
     * @param to      The resulting potion.
     */
    void addMix(Holder<Potion> from, Item reagent, Holder<Potion> to);

    /**
     * Registers a "starting" mix, the shorthand vanilla uses for a base ingredient: brewing {@code reagent}
     * on water yields {@code minecraft:mundane}, and brewing it on {@code minecraft:awkward} yields
     * {@code potion}.
     * <p>
     * Equivalent to {@code PotionBrewing.Builder#addStartMix}.
     *
     * @param reagent The item placed in the brewing stand's ingredient slot.
     * @param potion  The potion brewing this reagent on an awkward potion produces.
     */
    void addStartMix(Item reagent, Holder<Potion> potion);
}
